for (int i = 0; i < n; i++) pthread_create(&tid[i], NULL, ask, &jobs[i]);
struct timespec deadline = mono_now(); deadline.tv_sec += budget_ms / 1000;
pthread_mutex_lock(&g.m);
while (g.done < g.want) {
