epoll_add(ep, fd_of(recipient), EPOLLIN | EPOLLOUT);        /* fan out on writability */
while (pending > 0) {
    int ms = remaining_ms(deadline);
    if (ms <= 0) break;                                    /* budget exhausted: merge now */
    int k = epoll_wait(ep, evs, n, ms);
